args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?album ?albumLabel ?released WHERE {
  VALUES ?album { dbr:Freedom_for_the_Stallion dbr:In_the_Maybe_World }
  OPTIONAL { ?album dbp:released ?released. }
  OPTIONAL { ?album rdfs:label ?albumLabel. FILTER (lang(?albumLabel) = "en") }
}
ORDER BY ?released
LIMIT 1

